The evidence points to one root cause: ts-seat-service had a pod restart, and its failure propagated up to the user-facing dashboard. The food-service errors also appear in the normal period, so they are baseline noise.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name pod, metric, MIN(value) v0, MAX(value) v1, COUNT(*) n FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'ts-seat-service%' GROUP BY ALL", "claim": "ts-seat-service pod restart counter rises from 0 to 1 during the abnormal window, a restart event."},
        {"kind": "trace", "sql": "SELECT date_trunc('second', time) t, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-seat-service' AND time BETWEEN TIMESTAMPTZ '2025-08-15 20:48:40+00' AND TIMESTAMPTZ '2025-08-15 20:50:10+00' GROUP BY 1 ORDER BY 1", "claim": "Seat-service spans nearly stop for about 80 seconds (only 12 spans in 20:48:46-20:50:06), then resume at normal volume."},
        {"kind": "log", "sql": "SELECT service_name, LEFT(message, 260) msg, COUNT(*) n FROM abnormal_logs WHERE level='SEVERE' AND message LIKE '%ts-seat-service%' GROUP BY ALL", "claim": "travel and travel2 SEVERE logs show connection refused on ts-seat-service left_tickets calls (98 and 45 times)."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "log", "sql": "SELECT service_name, COUNT(*) n FROM abnormal_logs WHERE level='SEVERE' AND service_name='ts-travel2-service' AND message LIKE '%Connection refused%seats/left_tickets%' GROUP BY 1", "claim": "travel2 fails 98 requests with Connection refused calling ts-seat-service during the restart."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "log", "sql": "SELECT service_name, COUNT(*) n FROM abnormal_logs WHERE level='SEVERE' AND service_name='ts-travel-service' AND message LIKE '%Connection refused%seats/left_tickets%' GROUP BY 1", "claim": "travel fails 45 requests with Connection refused calling ts-seat-service during the restart."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) srv5xx FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY ALL", "claim": "route-plan client calls to travel2 return 500 on 56 of 316 requests in the abnormal window."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) srv5xx FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY ALL", "claim": "route-plan client calls to travel return 500 on 28 of 400 requests in the abnormal window."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, COUNT(*) n, SUM(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) srv5xx FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL", "claim": "travel-plan client calls to route-plan return 500 on 84 of 207 requests in the abnormal window."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code code, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND attr_http_response_status_code>=500 AND span_name LIKE '%travelPlan%' GROUP BY ALL", "claim": "ui-dashboard server spans on travelPlan endpoints return 500 for 84 requests, matching the travel-plan failures."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code code, COUNT(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND attr_http_response_status_code>=500 AND span_name LIKE '%travel2service%' GROUP BY ALL", "claim": "ui-dashboard returns 500 on travel2 trips/left requests, 42 times in the abnormal window."}]}
